"use strict";var RockCommerceSite;(()=>{function RCSite(){this.locale="de-DE";this.currency="EUR";this.priceType="net";this.cartCount=0;this.debug=!1}
RCSite.prototype.init=function(config){for(let prop in config){this[prop]=config[prop]}
this.cartCount=localStorage.getItem("rc-cart-count");this.updateMagicElements();console.log(this)};RCSite.prototype.getPricing=function(el){el=el.closest("[rc-pricing]");return JSON.parse(el.getAttribute("rc-pricing"))};RCSite.prototype.getSelectedVariationsKey=function(el){var variations=el.querySelectorAll("[rc-variation]");var variationKey="";variations.forEach(function(variation){var name=variation.getAttribute("name");var value=variation.value;variationKey+=name+":"+value+"|"});return variationKey.slice(0,-1)};RCSite.prototype.getSelectedAccessories=function(el){var accessories=el.querySelectorAll("[rc-accessory]:checked");return Array.from(accessories).map(function(accessory){return accessory.getAttribute("rc-accessory")})};RCSite.prototype.money=function(number){return new Intl.NumberFormat(this.locale,{currency:this.currency,style:"currency",}).format(number)};RCSite.prototype.updateMagicElements=function(){var magicelements={"rc-cart-count":this.cartCount,};for(var prop in magicelements){var elements=document.querySelectorAll("["+prop+"]");for(var i=0;i<elements.length;i++){elements[i].textContent=magicelements[prop];elements[i].removeAttribute("hidden")}}};RCSite.prototype.updatePrice=function(el){let root=el.closest("[rc-pricing]");let pricing=this.getPricing(root);let price=root.querySelector("[rc-price]");let varKey=this.getSelectedVariationsKey(root);let varPrice=pricing.variations[varKey];let total=varPrice.net*1;let accessories=this.getSelectedAccessories(root);accessories.forEach(function(id){let accPrice=pricing.accessories[id];console.log(accPrice);total+=accPrice.net*1});price.textContent=this.money(total)};RockCommerceSite=new RCSite();document.addEventListener("change",function(e){let el=e.target;if(el.closest("[rc-variation]")||el.closest("[rc-accessory]")){RockCommerceSite.updatePrice(el)}})})()